import{_ as o,o as a,c as n,a2 as r}from"./chunks/framework.BXzK3EA4.js";const q=JSON.parse('{"title":"AI 影视公司面试:部门领导会问什么","description":"这是面一家 AI 服务器厂商的 AI 短剧创作平台方向(部门领导终面)的完整准备清单,脱敏版。 按顺序过一遍大概 30-40 分钟。前四节是必须能答出来的,后面是查漏和临场工具。","frontmatter":{},"headers":[],"relativePath":"agent/projects/5-ai-film-production-interview.md","filePath":"agent/projects/5-ai-film-production-interview.md","lastUpdated":1793932732000}'),s={name:"agent/projects/5-ai-film-production-interview.md"};function d(l,t,e,i,p,u){return a(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="ai-影视公司面试-部门领导会问什么" tabindex="-1">AI 影视公司面试:部门领导会问什么 <a class="header-anchor" href="#ai-影视公司面试-部门领导会问什么" aria-label="Permalink to &quot;AI 影视公司面试:部门领导会问什么&quot;">​</a></h1><blockquote><p>这是面一家 AI 服务器厂商的 <strong>AI 短剧创作平台</strong>方向(部门领导终面)的完整准备清单,脱敏版。</p><p>按顺序过一遍大概 30-40 分钟。<strong>前四节是必须能答出来的,后面是查漏和临场工具。</strong></p></blockquote><h2 id="一、自我介绍-90-秒" tabindex="-1">一、自我介绍(90 秒) <a class="header-anchor" href="#一、自我介绍-90-秒" aria-label="Permalink to &quot;一、自我介绍(90 秒)&quot;">​</a></h2><h3 id="骨架" tabindex="-1">骨架 <a class="header-anchor" href="#骨架" aria-label="Permalink to &quot;骨架&quot;">​</a></h3><p><strong>身份定位 → 三个代表作 → 收尾落到&quot;我能给这个方向带来什么&quot;</strong></p><h3 id="参考稿" tabindex="-1">参考稿 <a class="header-anchor" href="#参考稿" aria-label="Permalink to &quot;参考稿&quot;">​</a></h3><blockquote><p>面试官好,我叫 XX,7 年前端,一直做 B 端中后台和可视化平台。</p><p><strong>第一是复杂后台和可视化。</strong> 做过智能风控的规则引擎 —— 多层嵌套条件、组合逻辑、操作符的可视化配置,还带指标管理中台;也做过农业 IoT 大屏,对接温湿度、光照、CO2、土壤墒情这些传感器实时上报,还有多摄像头预览、分屏和云台控制。ECharts 大屏、地图点位联动、实时数据刷新这一套我熟到能直接上手。</p><p><strong>第二是前端基建。</strong> 自己写过一套 RUM 错误监控和自动埋点 SDK —— React Fiber 往上遍历找事件处理器,实现零侵入点击采集,加了滑动窗口限流防雪崩。也做过 swagger 契约自动生成类型和统一请求 SDK。主导过 Vue2 到 Vue3 + Vite 的整体迁移,冷启动从 30 秒多降到 1 秒级,构建产物小了三成。</p><p><strong>第三是安全和合规。</strong> 按钮级权限、动态路由、登录安全、请求加密、富文本安全渲染,在配合渗透测试整改的时候全套做过 —— 我知道政企、金融、网安这类客户对权限和审计的要求有多严。</p><p><strong>再补一块最近的。</strong> 知道公司在往 AI 短剧方向走之后,我把主流的 AI 创作平台都用了一遍 —— WorkRally、腾讯云创意工坊、即梦、可灵,重点看它们的产品结构:剧本和分镜怎么组织、几千个生成任务怎么排队和反馈、多模型怎么统一接入、资产和成片怎么管。我还自己动手用 Next.js + FastAPI 写了个小工具,把&quot;批量提交 → 队列 → SSE 推进度 → 候选对比 → 结果入库&quot;这条链路串了一遍。</p><p>我看了贵司官网,最打动我的是&quot;<strong>软硬件一体化技术架构与研-产-销-服全链路体系</strong>&quot;和&quot;<strong>专注 AI 垂直领域智能体的开发与应用</strong>&quot; —— 不是单纯卖硬件,是把芯片、硬件、算法、场景一路串起来做成智能体。</p><p>这也是我想来的原因:纯做业务页面的活儿我做得够多了。我想接的是<strong>平台和场景层的东西</strong> —— 而 AI 短剧这个方向,恰好是我看过、用过、还动手写了一点的东西。</p></blockquote><p><strong>注意</strong>:最后一段是核心,一定要落到&quot;我能带来什么&quot;。提到方向时用对方的原词(软硬一体、垂直智能体),领导一听就知道你真去看了。</p><h2 id="二、通用软题-必问" tabindex="-1">二、通用软题(必问) <a class="header-anchor" href="#二、通用软题-必问" aria-label="Permalink to &quot;二、通用软题(必问)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>问题</th><th>答法方向</th></tr></thead><tbody><tr><td>1</td><td>简单介绍一下你自己</td><td>见上一节,90 秒,收尾落到 AI 短剧</td></tr><tr><td>2</td><td>⭐ 上一份工作为什么结束</td><td>真实原因自己清楚就行,<strong>关键是整场面试用同一套说法</strong>。理由只讲一次,补充细节不换主线</td></tr><tr><td>3</td><td>⭐ 为什么来这家、为什么不跟着推荐人去别家</td><td>&quot;方向认可,不是跟着人跑&quot;。理由落在软硬一体 + 真落地场景 + AI 短剧方向</td></tr><tr><td>4</td><td>你对我们公司了解多少</td><td>官网定位原话 + 双品牌 + 三个软件平台 + 公司名含义(昇=昇腾、伟=英伟达、线程=算力最小单元)</td></tr><tr><td>5</td><td>三到五年规划</td><td>业务页面 → 基建体系 → 平台与场景层产品</td></tr><tr><td>6</td><td>你的短板</td><td>模型侧 + 生产级后端 + 硬件知识;给方法论:&quot;先找到离我最近的抽象层&quot;</td></tr><tr><td>7</td><td>期望薪资</td><td>给区间不给死数字,见第七节</td></tr><tr><td>8</td><td>能接受创业公司节奏吗</td><td>拿远程协作项目举证(没人催、靠自律)→ 说明适应力;末尾反问一句真实交付节奏</td></tr><tr><td>9</td><td>会不会待不久</td><td>用两段经历的时长举证 + 这次是方向选择不是机会选择</td></tr><tr><td>10</td><td>带人/管理吗</td><td>诚实:IC 优先,但带过组件库和技术规范</td></tr></tbody></table><h3 id="q2-的三套答法-选一套-别混" tabindex="-1">Q2 的三套答法(选一套,别混) <a class="header-anchor" href="#q2-的三套答法-选一套-别混" aria-label="Permalink to &quot;Q2 的三套答法(选一套,别混)&quot;">​</a></h3><ul><li><p><strong>A. 远程协作项目结束/收缩</strong></p><blockquote><p>&quot;上一段是海外业务的远程协作项目,到 2026 年 8 月那波业务调整就自然收尾了。远程协作对自律要求高,我把这几年该沉淀的都沉淀下来了 —— 监控 SDK、请求层、组件库。现在想进一家实体团队,往平台方向再走一步。&quot;</p></blockquote></li><li><p><strong>B. 个人/家庭原因</strong>(保持简短,别展开隐私)</p><blockquote><p>&quot;主要是个人原因,那段时间也正好在看机会。说实话我关注的点很明确:想做平台和基建,不是纯业务需求交付。&quot;</p></blockquote></li><li><p><strong>C. 想换方向</strong></p><blockquote><p>&quot;我想从纯业务前端往<strong>平台型前端</strong>转 —— 设备纳管、算力调度、可视化编排这类活儿,纯 CRUD 练不出来。我看到这边有异构算力调度和无人设备统一纳管,正好是我想深挖的方向。&quot;</p></blockquote></li></ul><p><strong>通用收尾句</strong>(三套都用):</p><blockquote><p>&quot;不过这都不是重点,我这次来是冲着具体方向来的 —— 这个软硬一体的路子是我认真看过之后的选择,不是海投。&quot;</p></blockquote><h2 id="三、岗位相关题-这次的重头" tabindex="-1">三、岗位相关题(这次的重头) <a class="header-anchor" href="#三、岗位相关题-这次的重头" aria-label="Permalink to &quot;三、岗位相关题(这次的重头)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>问题</th><th>答法方向</th></tr></thead><tbody><tr><td>11</td><td>了解 AI 影视吗?讲讲 WorkRally / 即梦 / 可灵</td><td>WorkRally 定性:<strong>面向精品漫剧(及仿真人剧)的工业级 AI 流水线平台</strong>,不是单点生成工具;解决角色一致性 / 连镜 / 工具链割裂 / 产能瓶颈;指标<strong>产能约 5 倍、成本约 -50%</strong>。再报三个数:短剧市场规模、单集成本、集数时长</td></tr><tr><td>12</td><td>简单模式和画布模式差别在哪</td><td>简单模式 = 抽卡;画布模式 = 工程化,真正解决的是<strong>一致性</strong>(把角色/场景做成可绑定可复用的资产)。代价是复杂度,而复杂度就是前端的战场</td></tr><tr><td>13</td><td>⭐ <strong>Agent 是怎么做的?</strong></td><td><strong>唯一必须逐字背的一题</strong>,见 <a href="/agent/agent-advanced/6-agent-principles">Agent 原理</a> 的 1.1-1.4</td></tr><tr><td>14</td><td>WorkRally 的&quot;专家级 Agent&quot;是什么</td><td>多个专职 Agent(剧本/角色/分镜/提示词/超分)串成流水线,每个 Agent 是一个画布节点 —— 对应官网&quot;垂直领域智能体&quot;</td></tr><tr><td>15</td><td>⭐ AI 短剧平台最难的技术问题是什么</td><td>模型侧:<strong>一致性和多人同框对话戏</strong>(单人镜头是当前模型的舒适区,两人同框要动作自然、口型对上、身份不漂、空间关系正确);工程侧:<strong>把几千个任务的长链路变成人可用的工作台</strong></td></tr><tr><td>16</td><td>前端在这个平台里干什么</td><td>画布编排、批量任务队列、候选版本对比、一致性绑定、成本可视化、资产库、流式渲染</td></tr><tr><td>17</td><td>会 Python 吗?能写后端吗</td><td>三明治:定位(前端为主能串起前后端)→ 已有(基础语法 + 接口形态认知)→ 马上能干的(FastAPI+SSE / 任务队列 / 调模型 API)→ 一周计划(FastAPI·asyncio·Pydantic·SQLAlchemy·Redis·Celery·ffmpeg·Docker)→ 杀手锏(&quot;过去两年没人教我,我自己做了三个 SDK&quot;)</td></tr><tr><td>18</td><td>模型自研还是接第三方</td><td>早期接第三方跑通形态,但要做一致性引擎必须有自己的编排层。<strong>对前端的意义</strong>:接第三方 = 界面要为&quot;异步、时长不可控、参数各异&quot;设计</td></tr><tr><td>19</td><td>⭐ <strong>为什么这家要做 AI 短剧</strong></td><td>一部剧 80-100 集 × 每集 60 镜头 × 候选倍数 = <strong>万级 GPU 任务</strong> → 消化自有液冷算力 + 验证集群能扛生产级负载 + 对外卖降本后的工业化产能。<strong>他们要卖的不是片子,是跑通流水线的算力和平台</strong></td></tr><tr><td>20</td><td>短剧成本怎么控制</td><td>界面这块:<strong>把成本做成用户看得见的</strong> —— 每集多少卡时、哪个模型更划算、哪类镜头抽卡最多、是否超预算</td></tr><tr><td>21</td><td>一致性问题前端做什么</td><td>工作流(参考图做成可复用绑定)+ 可视化校验(这镜头的角色版本和上一镜是不是同一个)+ 候选管理(达标的沉淀成标准资产)</td></tr><tr><td>22</td><td>AI 生成内容的合规要求</td><td><strong>AIGC 显著标识 + 水印 + 溯源存证 + 送审链路</strong>,是产品硬功能不是法务文档。你做过渗透整改和权限审计,直接对口</td></tr><tr><td>23</td><td>如果让你设计分镜编辑器</td><td>四区联动(镜头列表 / 画面时间线 / 参数与一致性绑定),核心取舍是<strong>不让用户等</strong>:提交后立刻给位置感和可重试</td></tr><tr><td>24</td><td>两种形态(真人仿真 / 漫剧)都做,架构怎么设计</td><td><strong>统一角色资产层 + 两条生成路线</strong>:底层角色ID/多视角参考图/绑定关系/版本历史共用,差异收在参数层;资产层和任务队列层必须共用。类比你做过的指标管理中台 —— 上面不同数据源,下面统一抽象</td></tr></tbody></table><h3 id="关于第-19-题的完整话术-可直接说出口" tabindex="-1">关于第 19 题的完整话术(可直接说出口) <a class="header-anchor" href="#关于第-19-题的完整话术-可直接说出口" aria-label="Permalink to &quot;关于第 19 题的完整话术(可直接说出口)&quot;">​</a></h3><blockquote><p>&quot;我算过一笔账:一部短剧 80-100 集,一集 60 个镜头,每个镜头还要生成好几个候选,推理量是<strong>万级 GPU 任务</strong>。所以 AI 短剧本质是个算力消耗大户。</p><p>这就解释了为什么要做它 —— <strong>不是内容逻辑,是算力逻辑</strong>。液冷服务器公司的核心优势就是单位算力成本和高密度部署,正好对上短剧这种海量推理负载;而且跑通了真实的生产负载,才算证明这套集群能扛工业化生产 —— 这就是官网说的&#39;研-产-销-服全链路&#39;。再叠上&#39;专注 AI 垂直领域智能体&#39;这句,AI 短剧就是垂直智能体战略的第一个大场景。</p><p><strong>他们要卖的不是片子,是跑通这条流水线的算力和平台。</strong>&quot;</p></blockquote><h2 id="四、技术题-初面已过-备查" tabindex="-1">四、技术题(初面已过,备查) <a class="header-anchor" href="#四、技术题-初面已过-备查" aria-label="Permalink to &quot;四、技术题(初面已过,备查)&quot;">​</a></h2><p>部门领导一般不深挖,但会挑一两个问你&quot;你的技术判断&quot;。</p><table tabindex="0"><thead><tr><th>#</th><th>问题</th><th>备查要点</th></tr></thead><tbody><tr><td>25</td><td>Vue2 → Vue3 + Vite 迁移为什么做、收益</td><td>冷启动 30s+ → 1s 级、产物 -30%+、HMR 2s → 50ms</td></tr><tr><td>26</td><td>你的监控 SDK 怎么设计的</td><td>错误分类、滑动窗口限流、特殊错误码静默丢弃、React Fiber 遍历找事件处理器</td></tr><tr><td>27</td><td>组件库怎么设计的</td><td>30+ 业务组件、列表查询/表单提交/权限操作/金额录入四类高频</td></tr><tr><td>28</td><td>权限与安全怎么做</td><td>按钮级权限 + 动态路由 + 登录安全 + 请求加密 + 富文本安全渲染 + 渗透整改配合</td></tr><tr><td>29</td><td>大屏性能怎么优化</td><td>ECharts、实时刷新节流、地图点位联动、虚拟滚动</td></tr><tr><td>30</td><td>Agent 相关的技术题</td><td>见 <a href="/agent/agent-advanced/6-agent-principles">Agent 原理</a> 的失败模式清单 —— <strong>能说清根因和对策,比会背名词强十倍</strong></td></tr></tbody></table><h2 id="五、反问-必问前四个" tabindex="-1">五、反问(必问前四个) <a class="header-anchor" href="#五、反问-必问前四个" aria-label="Permalink to &quot;五、反问(必问前四个)&quot;">​</a></h2><ol><li><strong>&quot;这条线现在是从零开始,还是已经有人在做了?团队多少人、前端几个人?&quot;</strong></li><li><strong>&quot;做的是真人仿真短剧还是漫剧?两个的一致性方案和前端形态差别很大。&quot;</strong></li><li><strong>&quot;模型是自研还是接第三方?生成是分钟级还是小时级,界面设计完全不同。&quot;</strong></li><li>⭐ <strong>&quot;如果用第三方模型 API,自家的液冷服务器在这条链上扮演什么角色?&quot;</strong> —— <strong>这题最高级</strong>:既证明你懂整盘业务逻辑,又在替他的服务器找位置,他会很想回答</li><li>&quot;GPU 算力是自建集群跑,还是先租用云上的?&quot;</li><li>&quot;平台是从零做,还是基于某个开源工作流底座改?&quot;</li><li>&quot;前端是纯 Web 工作台,还是要往剪辑类专业工具方向做?&quot;</li><li>&quot;AIGC 标识和版权存证,产品侧怎么规划?&quot;</li><li>&quot;深圳和成都怎么分工?前端团队在哪个城市、几个人?&quot;</li><li>&quot;这个岗位职级和汇报对象是谁?&quot;</li><li>&quot;入职后三个月你最希望我做出什么?&quot;</li></ol><p><strong>不要问</strong>:上市/融资计划 · 加班和加班费 · 什么时候出结果 · 直接问薪资数字。</p><h2 id="六、三个坑" tabindex="-1">六、三个坑 <a class="header-anchor" href="#六、三个坑" aria-label="Permalink to &quot;六、三个坑&quot;">​</a></h2><ol><li><strong>离职原因前后不一</strong> —— 不需要跟谁对口径,但整场面试要用同一套说法。进面前把真实原因收敛成&quot;一句话主线 + 一个补充细节&quot;。</li><li><strong>姿态错了</strong> —— 部门领导面是&quot;同事之间判断要不要一起干活&quot;,不是下属面试。少用&quot;你们公司&quot;,多用&quot;咱们这边&quot;;少说&quot;都可以、听安排&quot;,多给判断。</li><li><strong>谈钱谈早谈死</strong> —— 给区间不给死数字,把话题从数字转向结构(绩效比例、职级、股权/期权)。</li></ol><h2 id="七、期望薪资" tabindex="-1">七、期望薪资 <a class="header-anchor" href="#七、期望薪资" aria-label="Permalink to &quot;七、期望薪资&quot;">​</a></h2><p><strong>原则:部门领导面尽量不谈死数字,谈区间 + 结构。</strong></p><ul><li>简历上的口径如果明显偏低,提前调高;被问到时给区间并留出谈判空间</li><li><strong>不要在领导面前主动压价</strong>(&quot;您给多少都行&quot;是自杀)</li><li><strong>把话题从数字转向结构</strong>:月薪 + 绩效比例 + 年终 + 职级 + 股权/期权</li><li>上市公司母体的子公司,核心团队的股权激励是可以问的 —— <strong>这是只有你知道公司背景才问得出的一句,直接拉高段位</strong></li></ul><p>被追问时的说法模板:</p><blockquote><p>&quot;我现在的诉求是<strong>月薪 XX-XXK 这个区间</strong>,具体看岗位职责和团队结构。另外我更关心整体的薪酬结构 —— 绩效和年终的比重、以及是否有面向核心团队的技术股权或期权激励,这块我都比较想了解。&quot;</p></blockquote><p>如果对方说给不了这么多:</p><blockquote><p>&quot;理解,那我想听听这个岗位的定位和空间 —— 如果职责本身有成长空间和成长速度,薪资我可以谈,但我需要一个能看到的路径,而不是只靠月薪数字。&quot;</p></blockquote><p><strong>不要在第一轮就认输降价。</strong></p><h2 id="八、面试前-30-分钟清单" tabindex="-1">八、面试前 30 分钟清单 <a class="header-anchor" href="#八、面试前-30-分钟清单" aria-label="Permalink to &quot;八、面试前 30 分钟清单&quot;">​</a></h2><p><strong>方向与公司</strong></p><ul><li>[ ] 背熟官网定位原话 + 双品牌 + 三个软件平台 + 公司名含义</li><li>[ ] 记住 WorkRally 定性与&quot;产能 5 倍 / 成本 -50%&quot;</li><li>[ ] 报得出三个数:短剧市场规模 / 单集成本 / 集数时长</li><li>[ ] 记住 2.1bis:两种形态都做 → 统一资产层 + 两条生成路线</li></ul><p><strong>自己</strong></p><ul><li>[ ] 自我介绍 90 秒稿,收尾落到 AI 短剧</li><li>[ ] 逐字背 Agent 那题(原理 + 影视落地两版)</li><li>[ ] 想好 Q15 最难问题、Q19 为什么做 AI 短剧、Q24 两种形态架构</li><li>[ ] 准备一个能讲 3 分钟的完整故事(不要流水账)</li><li>[ ] 离职原因收敛成一句话主线 + 一个补充细节</li></ul><p><strong>加分项</strong></p><ul><li>[ ] 带一个能跑的 mini demo(Next.js + FastAPI,走真实的&quot;批量提交 → 队列 → SSE 推进度 → 候选对比 → 结果入库&quot;结构),录 2-3 分钟屏防现场环境问题</li><li>[ ] 讲 demo 的落点是&quot;我不需要别人从头教我做接口&quot;,不是&quot;我做了个玩具&quot;</li></ul><h2 id="九、一页速记卡" tabindex="-1">九、一页速记卡 <a class="header-anchor" href="#九、一页速记卡" aria-label="Permalink to &quot;九、一页速记卡&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【一句话定位】7 年前端(B 端中后台 + 可视化 + 自研监控 SDK)+ 正在往 AI 平台走</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【三块弹药】</span></span>
<span class="line"><span>  复杂工作流界面   风控规则引擎 / 指标中台</span></span>
<span class="line"><span>  实时数据与设备   IoT 大屏 / 多摄像头 / 地图联动</span></span>
<span class="line"><span>  基建与合规       监控埋点 SDK / 契约驱动 / 权限审计</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【三个必答】</span></span>
<span class="line"><span>  Agent 怎么做的    LLM+工具+状态+循环;决定上限的是工具不是 prompt</span></span>
<span class="line"><span>  最难的问题        模型=一致性+多人同框;工程=几千任务的工作台</span></span>
<span class="line"><span>  为什么做 AI 短剧  万级 GPU 任务 → 算力逻辑,卖算力和平台不是卖片子</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【四个反问】</span></span>
<span class="line"><span>  团队几个人 / 真人还是漫剧 / 模型自研还是接第三方 /</span></span>
<span class="line"><span>  自家液冷服务器在这条链上扮演什么角色</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【三个别做】</span></span>
<span class="line"><span>  口径不一致 / 姿态像下属 / 谈钱谈死</span></span></code></pre></div><h2 id="🔗-延伸阅读" tabindex="-1">🔗 延伸阅读 <a class="header-anchor" href="#🔗-延伸阅读" aria-label="Permalink to &quot;🔗 延伸阅读&quot;">​</a></h2><ul><li><a href="/agent/projects/5-ai-film-production">AI 短剧生产平台(架构与产品)</a></li><li><a href="/agent/projects/5-ai-film-production-impl">AI 影视开发流程 · 具体实现</a></li><li><a href="/agent/projects/5-ai-film-production-agents">影视 Agent 流水线:六个 Agent 如何配合</a></li><li><a href="/agent/agent-advanced/6-agent-principles">Agent 原理:它到底在做什么,什么时候会失败</a></li><li><a href="/面试/复盘/1-前端面试复盘-2026-10">前端面试复盘:7 个问题的原理层答案</a> — 答在原理层的方法</li></ul><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>部门领导面考的不是&quot;能不能写代码&quot;,是<strong>靠不靠得住、能不能扛事、会不会待得住、跟团队合不合</strong>。</li><li><strong>主线</strong>:用你做过的复杂工作流界面、实时数据、设备接入,去证明你能接住 AI 短剧平台的编排层。</li><li><strong>必须逐字背的只有一题</strong>:Agent 怎么做的。其余可以现场组织。</li><li><strong>必须准备的一个数字逻辑</strong>:万级 GPU 任务 → 算力逻辑。这道题答好了,后面所有技术讨论你都在他的频道里。</li><li><strong>反问里最值钱的一问</strong>:自家液冷服务器在这条链上扮演什么角色。</li><li>心态:内部推荐 + 初面已过,你已经过了最难的两关。这场的及格线是<strong>让领导确认推荐人眼光准</strong>,不是表现惊艳。</li></ul>`,47)])])}const h=o(s,[["render",d]]);export{q as __pageData,h as default};
